<script setup lang="ts">import {Study} from '../types/domain';defineProps<{studies:Study[];modelValue:number}>();defineEmits<{"update:modelValue":[value:number]}>()</script><template><label>组成研究<select aria-label="组成研究" :value="modelValue" @change="$emit('update:modelValue',Number(($event.target as HTMLSelectElement).value))"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.code}} / {{s.name}} · {{s.supported?'可比较':'边界拒绝'}}</option></select></label></template>
